import{_ as t,o as a,c as r,ag as n}from"./chunks/framework.BPmc_f4o.js";const g=JSON.parse('{"title":"Subscription & Plans","description":"","frontmatter":{},"headers":[],"relativePath":"reference/subscription-plans.md","filePath":"reference/subscription-plans.md"}'),o={name:"reference/subscription-plans.md"};function i(s,e,l,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="subscription-plans" tabindex="-1">Subscription &amp; Plans <a class="header-anchor" href="#subscription-plans" aria-label="Permalink to &quot;Subscription &amp; Plans&quot;">​</a></h1><p>Muxit ships four tiers — <strong>Free</strong>, <strong>Maker</strong>, <strong>Pro</strong>, and <strong>Lab</strong>. Higher tiers include everything in the lower tiers; each row below links from the <strong>Plan Comparison</strong> table in <strong>Settings → Subscription</strong>, so you can jump straight from a feature to what it actually does.</p><p>Tiers and their limits are defined in the server (<code>AppSettings.Features</code>) and streamed to the UI, so the in-app comparison table is always an exact mirror of what the server enforces — this page is the human-readable companion to it.</p><table tabindex="0"><thead><tr><th>Feature</th><th style="text-align:center;">Free</th><th style="text-align:center;">Maker</th><th style="text-align:center;">Pro</th><th style="text-align:center;">Lab</th></tr></thead><tbody><tr><td><a href="#connectors">Connectors</a></td><td style="text-align:center;">3</td><td style="text-align:center;">10</td><td style="text-align:center;">∞</td><td style="text-align:center;">∞</td></tr><tr><td><a href="#concurrent-script-runs">Concurrent script runs</a></td><td style="text-align:center;">3</td><td style="text-align:center;">∞</td><td style="text-align:center;">∞</td><td style="text-align:center;">∞</td></tr><tr><td><a href="#extension-drivers">Extension drivers</a></td><td style="text-align:center;">5</td><td style="text-align:center;">∞</td><td style="text-align:center;">∞</td><td style="text-align:center;">∞</td></tr><tr><td><a href="#muxit-ai-chat">Muxit AI chat</a></td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td><a href="#ai-image-analysis">AI image analysis</a></td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td><a href="#local-llm">Local LLM</a></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td><a href="#remote-access">Remote access</a></td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td><a href="#label-printing">Label printing</a></td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td><a href="#mqtt-broker">MQTT broker</a></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td><a href="#autonomous-agents">Autonomous agents</a></td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">soon</td><td style="text-align:center;">soon</td></tr><tr><td><a href="#safety-policy-engine">Safety policy engine</a></td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td></tr><tr><td><a href="#custom-safety-levels">Custom safety levels</a></td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td></tr><tr><td><a href="#audit-log">Audit log</a></td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td></tr></tbody></table><p>Prices live at <a href="https://muxit.io/pricing" target="_blank" rel="noreferrer">muxit.io/pricing</a> and checkout at <a href="https://muxit.io/buy" target="_blank" rel="noreferrer">muxit.io/buy</a>. After purchase, paste the license key from your order e-mail under <strong>Settings → Subscription → Activate License</strong>. Premium drivers offer a per-driver trial from the same panel.</p><h2 id="connectors" tabindex="-1">Connectors <a class="header-anchor" href="#connectors" aria-label="Permalink to &quot;Connectors&quot;">​</a></h2><p><strong>Free 3 · Maker 10 · Pro / Lab unlimited.</strong> A connector is one configured device (an instrument, robot, camera, or compute engine). The limit counts connectors that are <em>loaded</em>, regardless of whether the underlying device is online.</p><h2 id="concurrent-script-runs" tabindex="-1">Concurrent script runs <a class="header-anchor" href="#concurrent-script-runs" aria-label="Permalink to &quot;Concurrent script runs&quot;">​</a></h2><p><strong>Free 3 · Maker+ unlimited.</strong> How many automation scripts may run at the same time. The cap is on <em>simultaneously running</em> scripts, not on how many script files you can keep in your workspace.</p><h2 id="extension-drivers" tabindex="-1">Extension drivers <a class="header-anchor" href="#extension-drivers" aria-label="Permalink to &quot;Extension drivers&quot;">​</a></h2><p><strong>Free 5 · Maker+ unlimited.</strong> DLL / packaged extension drivers (<code>.muxdriver</code>) installed into your workspace. Built-in drivers (Webcam, SCPI, TestDevice, …) never count against this limit.</p><h2 id="muxit-ai-chat" tabindex="-1">Muxit AI chat <a class="header-anchor" href="#muxit-ai-chat" aria-label="Permalink to &quot;Muxit AI chat&quot;">​</a></h2><p><strong>Maker and above.</strong> The built-in AI assistant and the script <code>ai()</code> global when they run against the <strong>Muxit-managed</strong> cloud model. Pointing Muxit at a <a href="#local-llm">local LLM</a> instead works on every tier, including Free.</p><h2 id="ai-image-analysis" tabindex="-1">AI image analysis <a class="header-anchor" href="#ai-image-analysis" aria-label="Permalink to &quot;AI image analysis&quot;">​</a></h2><p><strong>Maker and above.</strong> Lets the AI <em>see</em> a camera frame — the <code>take_snapshot</code> tool in chat and MCP, and image input to the script global <code>ai(prompt, snapshot)</code>. Free-tier calls that attach an image are blocked with an <code>IMAGE_ANALYSIS_REQUIRES_PRO</code> reason; text-only inference is unaffected.</p><p>This covers general &quot;look at this frame and describe it&quot; vision. It is distinct from the <strong>Vision engine</strong> — object detection, teach-by-example, calibration, and visual servoing — which ships as a separate premium extension (<code>Muxit.Driver.Vision</code>) that requires Pro plus its own license. In short: basic image analysis is a Maker capability; the dedicated computer-vision engine is where Pro pulls ahead.</p><h2 id="local-llm" tabindex="-1">Local LLM <a class="header-anchor" href="#local-llm" aria-label="Permalink to &quot;Local LLM&quot;">​</a></h2><p><strong>Every tier, including Free.</strong> Bring-your-own model over any OpenAI-compatible endpoint — Ollama, LM Studio, vLLM, llama-server, and similar. Local inference costs Muxit nothing per call, so chat and script <code>ai()</code> against your own model are free on every tier, and the offline / air-gapped story works without a subscription.</p><h2 id="remote-access" tabindex="-1">Remote access <a class="header-anchor" href="#remote-access" aria-label="Permalink to &quot;Remote access&quot;">​</a></h2><p><strong>Maker and above.</strong> Reach your Muxit server from outside the local machine (remote UI / tunnel access). See the <a href="/guides/remote-access.html">Remote Access guide</a>.</p><h2 id="label-printing" tabindex="-1">Label printing <a class="header-anchor" href="#label-printing" aria-label="Permalink to &quot;Label printing&quot;">​</a></h2><p><strong>Pro and above.</strong> Printing labels to a real printer with the built-in <a href="/reference/drivers/label-printer.html">LabelPrinter</a> driver — <code>print()</code>, <code>printBatch()</code>, <code>printImage()</code>, <code>printRaw()</code> and the Print buttons on the <strong>Tools → Label Printing</strong> page. Listing printers, creating printer connectors, editing templates, live previews (barcodes included: Code 128, Code 39/93, EAN, UPC, ITF, Codabar, QR, Data Matrix, PDF417, Aztec) and dry runs on the <code>null</code> backend are free on every tier, so a production line can be set up completely before upgrading. See the <a href="/guides/label-printing.html">Label Printing guide</a>.</p><h2 id="mqtt-broker" tabindex="-1">MQTT broker <a class="header-anchor" href="#mqtt-broker" aria-label="Permalink to &quot;MQTT broker&quot;">​</a></h2><p><strong>Every tier, including Free.</strong> The built-in MQTT bridge so homemade hardware (ESP32, Arduino, and friends) can publish and subscribe without a paid plan. See <a href="/guides/mqtt-iot.html">MQTT &amp; IoT</a>.</p><h2 id="autonomous-agents" tabindex="-1">Autonomous agents <a class="header-anchor" href="#autonomous-agents" aria-label="Permalink to &quot;Autonomous agents&quot;">​</a></h2><p><strong>Pro and above — coming soon.</strong> Long-running AI agents that pursue a goal across many tool calls. This feature is not yet generally available, so it appears as &quot;soon&quot; rather than a checkmark and is hidden from the in-app comparison table until it ships.</p><h2 id="safety-policy-engine" tabindex="-1">Safety policy engine <a class="header-anchor" href="#safety-policy-engine" aria-label="Permalink to &quot;Safety policy engine&quot;">​</a></h2><p><strong>Lab only.</strong> Enforcement of per-connector <code>safety:</code> blocks — limits, confirms, rate caps, interlocks, safe states, and level overrides. On lower tiers the <a href="/guides/safety.html">Safety Gate</a> falls back to the global safety-level policy table.</p><h2 id="custom-safety-levels" tabindex="-1">Custom safety levels <a class="header-anchor" href="#custom-safety-levels" aria-label="Permalink to &quot;Custom safety levels&quot;">​</a></h2><p><strong>Lab only.</strong> Author your own named safety levels in addition to the built-in Observe / Assisted / Active / Unrestricted set. See the <a href="/guides/safety.html">Safety guide</a>.</p><h2 id="operator-mode" tabindex="-1">Operator mode <a class="header-anchor" href="#operator-mode" aria-label="Permalink to &quot;Operator mode&quot;">​</a></h2><p><strong>Pro and up.</strong> Lock a station to a dashboard: the full interface, editor and MCP are refused server-side, and only dashboard controls, scripts in the <code>operator/</code> folder and an optional read-only AI chat remain. See the <a href="/guides/operator-mode.html">Operator mode guide</a>. Kept working for 60 days after a lapse, so a production station never unlocks overnight.</p><h2 id="user-accounts" tabindex="-1">User accounts <a class="header-anchor" href="#user-accounts" aria-label="Permalink to &quot;User accounts&quot;">​</a></h2><p><strong>Pro and up.</strong> Admin, engineer and operator accounts with PIN sign-in, a sign-in policy (optional or required), and the person&#39;s name on audit rows. Global — useful for attribution on any install, not only a locked station. See the <a href="/guides/accounts.html">Accounts guide</a>. Same 60-day grace as operator mode.</p><h2 id="audit-log" tabindex="-1">Audit log <a class="header-anchor" href="#audit-log" aria-label="Permalink to &quot;Audit log&quot;">​</a></h2><p><strong>Lab only.</strong> An exportable, append-only audit trail of gated actions at <code>workspace/logs/audit.jsonl</code>. Lower tiers fall back to per-event logger output.</p>',36)])])}const p=t(o,[["render",i]]);export{g as __pageData,p as default};
